def dedupe(items):
    """Remove duplicates from *items* while preserving the order of first occurrence."""
    seen = set()
    result = []
    for x in items:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

# Example
if __name__ == "__main__":
    print(dedupe([1, 2, 1, 3, 2]))   # → [1, 2, 3]
